import React from 'react';
import { Routes, Route, Link } from 'react-router-dom';

// Simple components
const Home = () => (
  <div className="p-8 text-center">
    <h1 className="text-4xl font-bold text-primestone-900 mb-4">PrimeStone Investment</h1>
    <p className="text-lg text-neutral-600 mb-8">Welcome to your investment platform</p>
    <div className="space-x-4">
      <Link to="/login" className="bg-primestone-600 text-white px-6 py-3 rounded-lg">Login</Link>
      <Link to="/register" className="border-2 border-primestone-600 text-primestone-600 px-6 py-3 rounded-lg">Register</Link>
    </div>
  </div>
);

const Login = () => <div className="p-8 text-center"><h2 className="text-2xl">Login Page</h2></div>;
const Register = () => <div className="p-8 text-center"><h2 className="text-2xl">Register Page</h2></div>;
const Dashboard = () => <div className="p-8 text-center"><h2 className="text-2xl">Dashboard</h2></div>;

function App() {
  return (
    <div className="min-h-screen bg-gradient-to-b from-primestone-50 to-white">
      <nav className="bg-white shadow-lg p-4">
        <div className="max-w-7xl mx-auto flex justify-between">
          <Link to="/" className="text-xl font-bold text-primestone-900">PrimeStone</Link>
          <div className="space-x-4">
            <Link to="/login" className="text-primestone-600">Login</Link>
            <Link to="/register" className="text-primestone-600">Register</Link>
            <Link to="/dashboard" className="text-primestone-600">Dashboard</Link>
          </div>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto py-12">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/dashboard" element={<Dashboard />} />
        </Routes>
      </div>
    </div>
  );
}

export default App;
